import base64
from pathlib import Path

AUDITOR = Path('dev_tools/russianization_audit.py')
source = AUDITOR.read_text(encoding='utf-8')
old = '            "dynamic_loader_references", "generated_references", "test_references",\n            "shared_runtime_candidate",'
new = '            "dynamic_loader_references", "generated_references", "test_references", "reference_counts",\n            "shared_runtime_candidate",'
if old in source:
    source = source.replace(old, new, 1)
elif new not in source:
    raise SystemExit('Expected compact manifest column block was not found.')
AUDITOR.write_text(source, encoding='utf-8')

payload = ''
Path('.github/workflows/lint.yml').write_bytes(base64.b64decode(payload))
